package org.securemail.identity;

import com.sun.net.httpserver.*;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;
import java.io.*;
import java.net.*;
import java.security.KeyPair;
import java.util.*;
import java.util.concurrent.*;

/** Loopback-only onion origin; no automatic production deployment and no root-key transport. */
public final class IdentityHttpServer implements AutoCloseable {
    private final IdentityStore store;private final KeyPair service;private final HttpServer server;
    private final ThreadPoolExecutor workers=new ThreadPoolExecutor(2,2,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(16),r->{Thread t=new Thread(r,"aegis-identity-http");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
    private final ScheduledThreadPoolExecutor deadlines=new ScheduledThreadPoolExecutor(1,r->{Thread t=new Thread(r,"aegis-identity-deadline");t.setDaemon(true);return t;});
    private long window=System.nanoTime();private int count,controlCount,recheckCount;
    public IdentityHttpServer(InetSocketAddress bind,IdentityStore store,KeyPair service)throws IOException {if(bind.isUnresolved()||!bind.getAddress().isLoopbackAddress())throw new IOException("Identity доступен только через loopback за Tor onion service");this.store=Objects.requireNonNull(store);this.service=Objects.requireNonNull(service);if(!IdentityProtocol.id(service.getPublic().getEncoded()).equals(store.audience()))throw new IOException("Ключ сервиса не совпадает");System.setProperty("jdk.httpserver.maxConnections","32");System.setProperty("sun.net.httpserver.maxReqHeaders","16");System.setProperty("sun.net.httpserver.maxReqTime","15");System.setProperty("sun.net.httpserver.maxRspTime","15");server=HttpServer.create(bind,16);server.setExecutor(workers);server.createContext("/",this::handle);deadlines.setRemoveOnCancelPolicy(true);}
    public void start(){server.start();}
    public int port(){return server.getAddress().getPort();}
    private synchronized boolean rate(String operation){long now=System.nanoTime();if(now-window>=60_000_000_000L){window=now;count=0;controlCount=0;recheckCount=0;}if(operation==null)return ++count<=6000;return (operation.equals("isActive")||operation.equals("isStepUpActive")||operation.equals("managedAccount"))?++recheckCount<=4000:++controlCount<=600;}
    private void handle(HttpExchange x){byte[] body=new byte[0];String nonce=IdentityProtocol.nonce();ScheduledFuture<?> deadline=deadlines.schedule(x::close,15,TimeUnit.SECONDS);try{if(!x.getRequestMethod().equals("POST")||!x.getRequestURI().getRawPath().equals("/identity/v1")||x.getRequestURI().getRawQuery()!=null)throw new IdentityException("NOT_FOUND");Headers h=x.getRequestHeaders();String length=single(h,"Content-Length"),type=single(h,"Content-Type");if(h.containsKey("Transfer-Encoding")||h.containsKey("Content-Encoding")||length==null||!length.matches("[0-9]{1,5}")||type==null||!type.matches("(?i)application/json(?:;\\s*charset=utf-8)?"))throw new IdentityException("INVALID");int n=Integer.parseInt(length);if(n<2||n>IdentityProtocol.MAX_BODY)throw new IdentityException("LIMIT");if(!rate(null))throw new IdentityException("RATE_LIMIT");body=x.getRequestBody().readNBytes(n+1);if(body.length!=n)throw new IdentityException("INVALID");Map<String,Object> request=IdentityJson.parse(body);IdentityJson.keys(request,"operation","nonce","data");nonce=IdentityProtocol.nonceValue(IdentityJson.text(request,"nonce",43));String operation=IdentityJson.text(request,"operation",40);if(!rate(operation))throw new IdentityException("RATE_LIMIT");if(!(request.get("data") instanceof Map<?,?> raw))throw new IdentityException("INVALID");@SuppressWarnings("unchecked")Map<String,Object> data=(Map<String,Object>)raw;Object result=dispatch(operation,data);respond(x,200,nonce,body,Map.of("ok",true,"data",result,"serverTime",System.currentTimeMillis()));}catch(IdentityException e){try{respond(x,switch(e.code()){case "DENIED","AUTH","REAUTH_REQUIRED"->403;case "REPLAY","CONFLICT","INITIALIZED"->409;case "RATE_LIMIT"->429;default->400;},nonce,body,Map.of("ok",false,"error",Map.of("code",e.code(),"message","Запрос не разрешён"),"serverTime",System.currentTimeMillis()));}catch(IOException ignored){}}catch(Exception e){try{respond(x,400,nonce,body,Map.of("ok",false,"error",Map.of("code","INVALID","message","Некорректный запрос"),"serverTime",System.currentTimeMillis()));}catch(IOException ignored){}}finally{Arrays.fill(body,(byte)0);deadline.cancel(false);x.close();}}
    private Object dispatch(String operation,Map<String,Object> d){return switch(operation){
        case "managedAccount"->{IdentityJson.keys(d,"serviceKey","accountId","time","nonce","proof");yield Map.of("managed",store.managedAccount(bin(d,"serviceKey",44),text(d,"accountId",64),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64)));}
        case "register"->{IdentityJson.keys(d,"accountKey","deviceKey","recoveryKey","nickname","time","nonce","accountProof","deviceProof");IdentityStore.Session s=store.register(bin(d,"accountKey",44),bin(d,"deviceKey",44),bin(d,"recoveryKey",44),text(d,"nickname",80),num(d,"time"),text(d,"nonce",43),bin(d,"accountProof",64),bin(d,"deviceProof",64));yield session(s);}
        case "login"->{IdentityJson.keys(d,"accountId","deviceId","time","nonce","proof");yield session(store.login(text(d,"accountId",64),text(d,"deviceId",64),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64)));}
        case "challengeDevice"->{IdentityJson.keys(d,"accountId","deviceKey","time","nonce","proof");IdentityStore.DeviceChallenge c=store.challengeDevice(text(d,"accountId",64),bin(d,"deviceKey",44),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));yield Map.of("accountId",c.accountId(),"challenge",c.challenge(),"deviceKey",IdentityProtocol.b64(c.deviceKey()),"expiresAt",c.expiresAt());}
        case "approveDevice"->{IdentityJson.keys(d,"accountId","deviceId","generation","challenge","proof");store.approveDevice(text(d,"accountId",64),text(d,"deviceId",64),num(d,"generation"),text(d,"challenge",43),bin(d,"proof",64));yield Map.of("approved",true);}
        case "deviceRecoveryInspect"->{IdentityJson.keys(d,"recovery","time","nonce","proof");yield store.inspectDeviceRecovery(IdentityProtocol.decodeDeviceRecovery(IdentityProtocol.unb64(text(d,"recovery",1368),1024)),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));}
        case "recoverDevice"->{IdentityJson.keys(d,"accountId","challenge","accountProof","recoveryProof");store.recoverDevice(text(d,"accountId",64),text(d,"challenge",43),bin(d,"accountProof",64),bin(d,"recoveryProof",64));yield Map.of("approved",true,"sensitiveRecoveryPending",true);}
        case "stepUpChallenge"->{IdentityJson.keys(d,"capability","time","nonce","proof");Capability cap=cap(d);store.authorize(cap,"account.read",new byte[0],num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));IdentityStore.Challenge c=store.stepUpChallenge(cap.accountId,cap.deviceId,cap.generation);yield Map.of("accountId",c.accountId(),"deviceId",c.deviceId(),"challenge",c.challenge(),"expiresAt",c.expiresAt());}
        case "stepUp"->{IdentityJson.keys(d,"accountId","deviceId","generation","challenge","accountProof","deviceProof");store.stepUp(text(d,"accountId",64),text(d,"deviceId",64),num(d,"generation"),text(d,"challenge",43),bin(d,"accountProof",64),bin(d,"deviceProof",64));yield Map.of("reauthenticated",true);}
        case "issueCapability"->{IdentityJson.keys(d,"accountId","deviceId","generation","appId","proofKey","capabilities","ttl","time","nonce","deviceProof","appProof");if(!(d.get("capabilities") instanceof List<?> list)||list.isEmpty()||list.size()>Scope.values().length)throw new IdentityException("INVALID");Set<Scope> scopes=EnumSet.noneOf(Scope.class);for(Object value:list){if(!(value instanceof String name)||!scopes.add(Scope.valueOf(name)))throw new IdentityException("INVALID");}Capability cap=store.issueCapability(text(d,"accountId",64),text(d,"deviceId",64),num(d,"generation"),App.valueOf(text(d,"appId",20)),bin(d,"proofKey",44),scopes,num(d,"ttl"),num(d,"time"),text(d,"nonce",43),bin(d,"deviceProof",64),bin(d,"appProof",64));yield Map.of("capability",IdentityProtocol.encodeCapability(cap));}
        case "authorize","authorizeDigest"->{boolean digest=operation.equals("authorizeDigest");IdentityJson.keys(d,"capability","action",digest?"bodySha256":"body","time","nonce","proof");byte[] b=digest?bin(d,"bodySha256",32):IdentityProtocol.unb64(text(d,"body",49152),36000);VerifiedContext c=digest?store.authorizeDigest(cap(d),text(d,"action",96),b,num(d,"time"),text(d,"nonce",43),bin(d,"proof",64)):store.authorize(cap(d),text(d,"action",96),b,num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));yield context(c);}
        case "ownerBootstrapInspect"->{IdentityJson.keys(d,"capability","challenge","time","nonce","proof");yield store.inspectOwnerBootstrap(cap(d),text(d,"challenge",43),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));}
        case "ownerTransferChallenge"->{IdentityJson.keys(d,"capability","targetAccountId","time","nonce","proof");yield store.ownerTransferChallenge(cap(d),text(d,"targetAccountId",64),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));}
        case "ownerTransferInspect"->{IdentityJson.keys(d,"capability","challenge","time","nonce","proof");yield store.inspectOwnerTransfer(cap(d),text(d,"challenge",43),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));}
        case "ownerTransferComplete"->{IdentityJson.keys(d,"capability","challenge","requestId","ownerRootProof","ownerDeviceProof","targetRootProof","targetDeviceProof","time","nonce","proof");store.completeOwnerTransfer(cap(d),text(d,"challenge",43),text(d,"requestId",43),bin(d,"ownerRootProof",64),bin(d,"ownerDeviceProof",64),bin(d,"targetRootProof",64),bin(d,"targetDeviceProof",64),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));yield Map.of("transferred",true,"sessionsRevoked",true);}
        case "firstDelegateChallenge"->{IdentityJson.keys(d,"capability","targetAccountId","roleName","time","nonce","proof");yield store.firstDelegateChallenge(cap(d),text(d,"targetAccountId",64),text(d,"roleName",80),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));}
        case "firstDelegateInspect"->{IdentityJson.keys(d,"capability","challenge","time","nonce","proof");yield store.inspectFirstDelegation(cap(d),text(d,"challenge",43),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));}
        case "firstDelegateComplete"->{IdentityJson.keys(d,"challenge","ownerRootProof","ownerDeviceProof","targetRootProof","targetDeviceProof");store.completeFirstDelegation(text(d,"challenge",43),bin(d,"ownerRootProof",64),bin(d,"ownerDeviceProof",64),bin(d,"targetRootProof",64),bin(d,"targetDeviceProof",64));yield Map.of("delegated",true);}
        case "sensitiveRecoveryApprove"->{IdentityJson.keys(d,"capability","requestId","targetAccountId","time","nonce","proof");store.approveSensitiveRecovery(cap(d),text(d,"requestId",43),text(d,"targetAccountId",64),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));yield Map.of("approved",true);}
        case "administratorAssign"->{IdentityJson.keys(d,"capability","requestId","targetAccountId","roleName","time","nonce","proof");store.assignAdministrator(cap(d),text(d,"requestId",43),text(d,"targetAccountId",64),text(d,"roleName",80),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));yield Map.of("assigned",true);}
        case "administratorRevoke"->{IdentityJson.keys(d,"capability","requestId","targetAccountId","time","nonce","proof");store.revokeAdministrator(cap(d),text(d,"requestId",43),text(d,"targetAccountId",64),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));yield Map.of("revoked",true);}
        case "criticalRequest"->{IdentityJson.keys(d,"capability","operation","payload","time","nonce","proof");yield store.requestCritical(cap(d),text(d,"operation",64),IdentityProtocol.unb64(text(d,"payload",43692),32768),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));}
        case "criticalApprove"->{IdentityJson.keys(d,"capability","requestId","time","nonce","proof");store.approveCritical(cap(d),text(d,"requestId",43),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));yield Map.of("approved",true);}
        case "criticalConsume"->{IdentityJson.keys(d,"capability","requestId","operation","payload","time","nonce","proof");store.consumeCritical(cap(d),text(d,"requestId",43),text(d,"operation",64),IdentityProtocol.unb64(text(d,"payload",43692),32768),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));yield Map.of("consumed",true);}
        case "isStepUpActive"->{IdentityJson.keys(d,"capability");boolean active;try{active=store.isStepUpActive(cap(d));}catch(IllegalArgumentException|IdentityException denied){active=false;}yield Map.of("active",active);}
        case "isActive"->{IdentityJson.keys(d,"capability");boolean active;try{active=store.isActive(cap(d));}catch(IllegalArgumentException|IdentityException denied){active=false;}yield Map.of("active",active);}
        case "revoke"->{IdentityJson.keys(d,"capability","time","nonce","proof");store.revoke(cap(d),num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));yield Map.of("revoked",true);}
        case "profile"->{IdentityJson.keys(d,"capability","time","nonce","proof");Capability cap=cap(d);store.authorize(cap,"account.read",new byte[0],num(d,"time"),text(d,"nonce",43),bin(d,"proof",64));yield store.profile(cap.accountId);}
        default->throw new IdentityException("NOT_FOUND");};}
    private static Map<String,Object> session(IdentityStore.Session s){return Map.of("accountId",s.accountId(),"deviceId",s.deviceId(),"generation",s.generation(),"issuedAt",s.issuedAt(),"expiresAt",s.expiresAt());}
    private Map<String,Object> context(VerifiedContext c){List<String> scopes=c.capabilities.stream().map(Enum::name).sorted().toList();Map<String,Object> result=new LinkedHashMap<>(Map.of("accountId",c.accountId,"deviceId",c.deviceId,"appId",c.appId.name(),"generation",c.generation,"leaseUntil",c.leaseUntil,"capabilities",scopes));result.putAll(store.publicProfile(c.accountId));result.putAll(store.currentAuthority(c.accountId));result.put("stepUpUntil",store.sessionStepUpUntil(c.accountId,c.deviceId,c.generation));return result;}
    private static Capability cap(Map<String,Object>d){return IdentityProtocol.decodeCapability(text(d,"capability",4096));}
    private static String text(Map<String,Object>d,String key,int max){return IdentityJson.text(d,key,max);}
    private static long num(Map<String,Object>d,String key){return IdentityJson.number(d,key);}
    private static byte[] bin(Map<String,Object>d,String key,int size){return IdentityJson.binary(d,key,size);}
    private static String single(Headers h,String key){List<String> v=h.get(key);return v!=null&&v.size()==1?v.getFirst():null;}
    private void respond(HttpExchange x,int status,String nonce,byte[] request,Object value)throws IOException {byte[] body=IdentityJson.bytes(value);try{if(body.length>IdentityProtocol.MAX_BODY)throw new IOException("Response limit");Headers h=x.getResponseHeaders();h.set("Content-Type","application/json; charset=utf-8");h.set("Connection","close");h.set("Cache-Control","no-store");h.set("X-Content-Type-Options","nosniff");h.set("AEGIS-Signature",IdentityProtocol.b64(IdentityProtocol.sign(service.getPrivate(),IdentityProtocol.response(store.audience(),nonce,request,body))));x.sendResponseHeaders(status,body.length);x.getResponseBody().write(body);}finally{Arrays.fill(body,(byte)0);}}
    @Override public void close(){server.stop(0);deadlines.shutdownNow();workers.shutdownNow();}
}
